SELECT id, order_date, channel, amount, discount, LAG(amount) OVER w_hist AS prev_amount, LEAD(amount) OVER w_hist AS next_amount, LAG(shipping_fee) OVER w_hist AS prev_shipping_fee, LEAD(shipping_fee) OVER w_hist AS next_shipping_fee, ROW_NUMBER() OVER w_hist AS event_seq FROM orders WHERE customer_id IN (7, 22, 36) WINDOW w_hist AS (PARTITION BY status ORDER BY shipping_fee, id);
